/**
 * Core Express middleware factory.
 *
 * Call `requestId(options?)` to create a middleware function and mount it
 * with `app.use(requestId())`.
 *
 * The factory validates all configuration at initialization time so that
 * misconfiguration surfaces immediately on startup rather than on the first
 * incoming request.
 */

import { defaults } from "../config/defaults.js";
import { generateUUID }    from "../generators/uuid.js";
import { generateNanoId }  from "../generators/nanoid.js";
import {
  assertValidGenerator,
  invokeCustomGenerator,
} from "../generators/custom.js";
import { validateRequestId } from "../utils/validator.js";
import { applyPrefix, assertValidPrefix, assertValidHeaderName } from "../utils/formatter.js";

/**
 * @typedef {object} RequestIdOptions
 * @property {string}    [headerName="X-Request-ID"] - Response header name.
 * @property {"uuid"|"nanoid"} [strategy="uuid"]     - Built-in ID strategy.
 * @property {string}    [prefix=""]                 - Optional ID prefix.
 * @property {boolean}   [useIncoming=false]         - Accept upstream IDs.
 * @property {boolean}   [validateIncoming=true]     - Validate upstream IDs.
 * @property {boolean}   [exposeHeader=true]         - Set response header.
 * @property {Function}  [generator]                 - Custom generator fn.
 */

/** @type {Set<"uuid"|"nanoid">} */
const BUILT_IN_STRATEGIES = new Set(["uuid", "nanoid"]);

/**
 * Merge user options with defaults and validate every field.
 *
 * @param {RequestIdOptions} opts
 * @returns {Required<RequestIdOptions>}
 */
function buildConfig(opts) {
  const cfg = { ...defaults, ...opts };

  // Validate headerName
  assertValidHeaderName(cfg.headerName);

  // Validate prefix
  assertValidPrefix(cfg.prefix);

  // Validate strategy vs generator
  if (cfg.generator !== undefined) {
    assertValidGenerator(cfg.generator);
  } else if (!BUILT_IN_STRATEGIES.has(cfg.strategy)) {
    throw new TypeError(
      `[@mohammed_kashif/requestid] Unknown strategy "${cfg.strategy}". ` +
      `Valid values: "uuid", "nanoid". ` +
      `To use a custom generator pass options.generator instead.`
    );
  }

  // Type-check boolean flags
  for (const flag of ["useIncoming", "validateIncoming", "exposeHeader"]) {
    if (typeof cfg[flag] !== "boolean") {
      throw new TypeError(
        `[@mohammed_kashif/requestid] options.${flag} must be a boolean, got: ${typeof cfg[flag]}`
      );
    }
  }

  return cfg;
}

/**
 * Generate a fresh request ID using the configured strategy.
 *
 * @param {Required<RequestIdOptions>} cfg
 * @returns {string}
 */
function generateId(cfg) {
  let raw;

  if (cfg.generator) {
    raw = invokeCustomGenerator(cfg.generator);
  } else if (cfg.strategy === "nanoid") {
    raw = generateNanoId();
  } else {
    raw = generateUUID();
  }

  return applyPrefix(raw, cfg.prefix);
}

/**
 * Express middleware factory for request ID management.
 *
 * @param {RequestIdOptions} [options={}]
 * @returns {import('express').RequestHandler}
 */
export function requestId(options = {}) {
  const cfg = buildConfig(options);

  return function requestIdMiddleware(req, res, next) {
    let id;

    // ── 1. Try to reuse an incoming ID ────────────────────────────────────
    if (cfg.useIncoming) {
      const incoming = req.headers[cfg.headerName.toLowerCase()];

      if (incoming) {
        if (cfg.validateIncoming) {
          const { valid } = validateRequestId(incoming);
          id = valid ? incoming : generateId(cfg);
        } else {
          // Developer explicitly opted out of validation — accept as-is.
          id = String(incoming);
        }
      }
    }

    // ── 2. Fall back to fresh generation ──────────────────────────────────
    if (!id) {
      id = generateId(cfg);
    }

    // ── 3. Attach to request ──────────────────────────────────────────────
    req.id = id;

    // ── 4. Set response header ────────────────────────────────────────────
    if (cfg.exposeHeader) {
      res.setHeader(cfg.headerName, id);
    }

    next();
  };
}
